#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <cmath>
#include <iostream>

using namespace fedspatial;
namespace {
double abs_err(const Matrix& a,const Matrix& b){return max_abs_diff(a,b);}
double rel_err(const Matrix& a,const Matrix& b){double e=0;for(size_t i=0;i<a.a.size();++i)e=std::max(e,std::abs(a.a[i]-b.a[i])/std::max(1e-300,std::abs(b.a[i])));return e;}
void report(const char* name,const Matrix& got,const Matrix& want,double& a,double& r){if(got.rows!=want.rows||got.cols!=want.cols)throw std::runtime_error(std::string(name)+" shape mismatch");const double x=abs_err(got,want),y=rel_err(got,want);a=std::max(a,x);r=std::max(r,y);std::cout<<name<<"_MAX_ABS="<<x<<'\n'<<name<<"_MAX_REL="<<y<<'\n';}
}
int main(){try{
  Matrix sites(3,2),z(3,1),x(3,1),knots(2,2),gamma(1,1),mu(2,1),sigma(2,2); const double sv[]={0,.1,.8,.3,.2,.9};const double kv[]={0,0,1,1};for(int i=0;i<6;++i)sites.a[i]=sv[i];for(int i=0;i<4;++i)knots.a[i]=kv[i];z.a={.3,-.2,.7};for(double&v:x.a)v=1.;gamma(0,0)=.15;mu(0,0)=.2;mu(1,0)=-.1;sigma(0,0)=.7;sigma(1,1)=.4;sigma(0,1)=sigma(1,0)=.05;WorkerInput w{sites,z,x};GlobalParameters p{gamma,mu,sigma,1.7,1.2,.8,3};
  GpuContext c(0);const auto state=build_device_mu_sigma_local(c,w,knots,p);const auto first=download_device_mu_sigma_local(c,state);GpuContext legacy_context(0);const auto legacy=compute_mu_sigma_local_legacy_oracle(legacy_context,w,knots,p);const auto cpu=make_local_p(sites,knots,z,x,gamma,p.delta,p.alpha,p.range);Matrix e=subtract(z,matmul(x,gamma)),minve=matmul(cpu.Minv,e),btminve=matmul(transpose(cpu.B),minve),chol=cholesky_lower(cpu.M);Matrix want_chol=chol;double logdet=0;for(int i=0;i<3;++i)logdet+=2*std::log(chol(i,i));logdet-=3*std::log(p.delta);Matrix rhs=subtract(matmul(cpu.B,mu),e);double objective=logdet;for(int i=0;i<3;++i)objective+=p.delta*rhs(i,0)*matmul(cpu.Minv,rhs)(i,0);for(int i=0;i<4;++i)objective+=p.delta*cpu.btMinvb.a[i]*sigma.a[i];
  double a=0,r=0;report("B",first.B,cpu.B,a,r);report("M",first.M,cpu.M,a,r);report("CHOL_M",first.chol_M,want_chol,a,r);report("E",first.e,e,a,r);Matrix want_minve=minve;for(double&v:want_minve.a)v*=p.delta;Matrix want_btminve=btminve;for(double&v:want_btminve.a)v*=p.delta;Matrix want_btminvb=cpu.btMinvb;for(double&v:want_btminvb.a)v*=p.delta;report("MINV_B",first.rinv_B,legacy.rinv_B,a,r);report("MINV_E",first.rinv_e,want_minve,a,r);report("BT_MINV_E",first.bt_rinv_e,want_btminve,a,r);report("BT_MINV_B",first.bt_rinv_B,want_btminvb,a,r);Matrix want_mu=btminve;for(double&v:want_mu.a)v=-v;report("SUMMARY_MU",first.summary.mu,want_mu,a,r);Matrix want_sigma=cpu.btMinvb;report("SUMMARY_SIGMA",first.summary.sigma,want_sigma,a,r);std::cout<<"MINV_B_PUBLIC_SHAPE="<<first.rinv_B.rows<<"x"<<first.rinv_B.cols<<"\n";
  const auto raw=c.raw_h2d_bytes(), d2h=c.result_d2h_bytes(), allocations=c.mu_sigma_allocation_count();const auto repeat=build_device_mu_sigma_local(c,w,knots,p);const bool transfers=c.raw_h2d_bytes()==raw && c.result_d2h_bytes()==d2h && c.mu_sigma_allocation_count()==allocations;const auto second=download_device_mu_sigma_local(c,repeat);double deterministic=std::max({abs_err(first.B,second.B),abs_err(first.M,second.M),abs_err(first.rinv_B,second.rinv_B),abs_err(first.bt_rinv_B,second.bt_rinv_B)});const double logdet_error=std::abs(first.logdet_R-logdet), quadratic_error=std::abs(first.et_rinv_e-p.delta*matmul(transpose(e),minve)(0,0)), objective_error=std::abs(first.local_objective-objective);const bool scalar=logdet_error<=1e-10&&quadratic_error<=1e-10&&objective_error<=1e-10;const bool ok=a<=1e-10&&r<=1e-9&&deterministic==0.&&transfers&&scalar;std::cout<<"DEVICE_MU_SIGMA_MAX_ABS="<<a<<"\nDEVICE_MU_SIGMA_MAX_REL="<<r<<"\nDEVICE_MU_SIGMA_EXACT_REPEAT="<<(deterministic==0.?"PASS":"FAIL")<<"\nDEVICE_MU_SIGMA_SCALAR_ERRORS="<<logdet_error<<","<<quadratic_error<<","<<objective_error<<"\nDEVICE_MU_SIGMA_SCALARS="<<(scalar?"PASS":"FAIL")<<"\nDEVICE_MU_SIGMA_PERSISTENT_ALLOCATIONS="<<(c.mu_sigma_allocation_count()==allocations?"PASS":"FAIL")<<"\nDEVICE_MU_SIGMA_ZERO_ACTIVE_MODEL_TRANSFERS="<<(transfers?"PASS":"FAIL")<<"\nDEVICE_MU_SIGMA_STATE_PARITY="<<(ok?"PASS":"FAIL")<<'\n';return ok?0:1;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
